#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;

    if (n % 3 != 0 || n <= 0) {
        cout << 0;
        return 0;
    }

    long long n1 = n / 3;
    long long count = 0;
    vector<long long> v;

    for (long long i = 2; i <= n1 / i; ++i) {
        if (n1 % i == 0) {
            v.push_back(i);
        }
    }

    for (size_t i = 0; i < v.size() &&
         (__int128)v[i] * v[i] * v[i] <= n1; ++i) {
        for (size_t j = i; j < v.size() &&
             (__int128)v[i] * v[j] * v[j] <= n1; ++j) {
            __int128 product = (__int128)v[i] * v[j];

            if (n1 % (long long)product == 0) {
                long long m = n1 / (long long)product;

                if (m != 1 && v[j] <= m) {
                    long long x = v[i] + v[j] + m;

                    if (x % 2 == 0) {
                        x /= 2;
                        long long a = x - v[i];
                        long long b = x - v[j];
                        long long c = x - m;

                        if (a > 0 && b > 0 && c > 0) {
                            if (a != b && b != c) {
                                count += 6;
                            } else if ((a == b && b != c) ||
                                       (b == c && c != a) ||
                                       (c == a && a != b)) {
                                count += 3;
                            } else {
                                count += 1;
                            }
                        }
                    }
                }
            }
        }
    }

    cout << count;
    return 0;
}

