             ++j) {
            __int128 product = (__int128)v[i] * v[j];
            if (n1 % (long long)product != 0) continue;

            long long m = n1 / (long long)product;
            if (m == 1 || v[j] > m) continue;

            long long x = v[i] + v[j] + m;
            if (x % 2 != 0) continue;

            x /= 2;
            long long a = x - v[i];
            long long b = x - v[j];
            long long c = x - m;

            if (a <= 0 || b <= 0 || c <= 0) continue;

            if (a == b && b == c) {
                count += 1;
            } else if (a == b || b == c || c == a) {
                count += 3;
            } else {
                count += 6;
            }
        }
    }

    cout << count;
    return 0;
}

